// Stage 01 refinement (Phase 04, owner brief 24 Nov 2026): the painted world around the yard. Every 3D tree is
// gone (cone trees, midground impostors and tree cutouts); six layered matte paintings wrap the course on
// cylinders at different radii (sky clouds, far landscape, industrial skyline, forest silhouettes, midground
// structures, foreground mist), so they slide against each other as the camera moves (lightweight parallax).
// The cloud layer drifts slowly. Placement: blender/exports/stage01/matte/STAGE_01_MATTE_LAYERS.json, generated by
// tools/stage01/generate_matte_layers.py. Decorative only: no collision, no gameplay effect.
import { useFrame } from '@react-three/fiber';
import { useEffect, useMemo } from 'react';
import * as THREE from 'three';
import manifest from '../../../../../blender/exports/stage01/matte/STAGE_01_MATTE_LAYERS.json';
import skyUrl from '../../../../../blender/exports/stage01/matte/MP01_Sky.webp?url';
import landUrl from '../../../../../blender/exports/stage01/matte/MP02_FarLandscape.webp?url';
import forestUrl from '../../../../../blender/exports/stage01/matte/MP03_ForestSilhouettes.webp?url';
import skylineUrl from '../../../../../blender/exports/stage01/matte/MP04_IndustrialSkyline.webp?url';
import midUrl from '../../../../../blender/exports/stage01/matte/MP05_MidStructures.webp?url';
import fgUrl from '../../../../../blender/exports/stage01/matte/MP06_Foreground.webp?url';
import type { Quality } from '../../game/quality.ts';
import { FOG } from './fog.ts';

const LAYER_URL: Record<string, string> = {
  MP01_Sky: skyUrl, MP02_FarLandscape: landUrl, MP03_ForestSilhouettes: forestUrl,
  MP04_IndustrialSkyline: skylineUrl, MP05_MidStructures: midUrl, MP06_Foreground: fgUrl,
};

/** Load status for tests (window.__cn.assets().surroundings). `cutouts` stays 0: tree cutouts are retired. */
export const surroundingsStatus = { layers: 0, cutouts: 0, fog: 'none', problems: [] as string[] };

const loader = new THREE.TextureLoader();
function loadTexture(url: string, onError: (e: unknown) => void) {
  const t = loader.load(url, undefined, undefined, onError);
  t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = 4;
  return t;
}

/** Open cylinder facing inward, u = 0 toward +Z, increasing toward +X (the manifest's convention). */
function layerGeometry(radius: number, height: number, bottom: number, uOffset: number, gloom = 0.7, segments = 128) {
  const pos: number[] = [], uv: number[] = [], idx: number[] = [], col: number[] = [];
  for (let i = 0; i <= segments; i++) {
    const u = i / segments;
    const a = u * Math.PI * 2;
    const x = Math.sin(a) * radius, z = Math.cos(a) * radius;
    pos.push(x, bottom, z, x, bottom + height, z);
    // Darker toward The Watcher (u = 0.5 faces -Z): the painted world falls into gloom behind the doll. Not on
    // the translucent cloud and mist layers, where darkening would show as a dark band in the sky.
    const k = 1 - gloom * Math.exp(-(((u - 0.5) / 0.09) ** 2));
    col.push(k, k, k, k, k, k);
    uv.push(u + uOffset, 0, u + uOffset, 1);
    if (i < segments) { const k = i * 2; idx.push(k, k + 2, k + 1, k + 1, k + 2, k + 3); }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
  g.setAttribute('color', new THREE.Float32BufferAttribute(col, 3));
  g.setIndex(idx);
  return g;
}

function MatteLayers({ quality }: { quality: Quality }) {
  const group = useMemo(() => {
    const g = new THREE.Group();
    g.name = 'STG01_MatteLayers';
    g.position.set(manifest.centre[0], 0, manifest.centre[2]);
    for (const l of manifest.layers) {
      const tex = loadTexture(LAYER_URL[l.id], () => surroundingsStatus.problems.push(`matte layer ${l.id} failed to load`));
      tex.wrapS = THREE.RepeatWrapping;
      tex.userData.drift = l.drift ?? 0;
      const mat = new THREE.MeshBasicMaterial({ map: tex, color: new THREE.Color().setScalar(l.brightness ?? 1), vertexColors: true, transparent: true, depthWrite: false, side: THREE.DoubleSide, fog: false, toneMapped: false });
      // Decision 031: the painted backdrop sits behind the fog, so it fades toward the fog colour.
      mat.onBeforeCompile = (sh) => {
        sh.uniforms.uFogTint = { value: FOG.color };
        sh.uniforms.uFogTintMix = { value: l.fogMix ?? FOG.backdropMix };
        sh.fragmentShader = 'uniform vec3 uFogTint; uniform float uFogTintMix;\n' + sh.fragmentShader.replace('#include <opaque_fragment>',
          '#include <opaque_fragment>\n  gl_FragColor.rgb = mix(gl_FragColor.rgb, uFogTint, uFogTintMix);');
      };
      const mesh = new THREE.Mesh(layerGeometry(l.radius, l.height, l.bottom, l.uOffset, l.id === 'MP01_Sky' || l.id === 'MP06_Foreground' ? 0 : 0.7), mat);
      mesh.name = l.id;
      mesh.renderOrder = -10 + l.order; // far layers first; they never write depth
      mesh.frustumCulled = false;
      g.add(mesh);
    }
    surroundingsStatus.layers = manifest.layers.length;
    surroundingsStatus.fog = `backdrop mix ${FOG.backdropMix}`;
    return g;
  }, []);
  // Slow cloud drift (texture offset only; no geometry work). Held still on the low tier.
  useFrame((_, dt) => {
    if (quality === 'low') return;
    for (const o of group.children) {
      const map = ((o as THREE.Mesh).material as THREE.MeshBasicMaterial).map;
      if (map?.userData.drift) map.offset.x = (map.offset.x + map.userData.drift * Math.min(dt, 0.1)) % 1;
    }
  });
  useEffect(() => () => {
    group.traverse((o) => { const m = o as THREE.Mesh; if (m.isMesh) { m.geometry.dispose(); const mat = m.material as THREE.MeshBasicMaterial; mat.map?.dispose(); mat.dispose(); } });
  }, [group]);
  return <primitive object={group} />;
}

export function Surroundings({ quality }: { quality: Quality }) {
  return <MatteLayers quality={quality} />;
}
